      "speaker": "bot",
      "text": "Hello दीपक।"
    },
    {
      "i": 1,
      "speaker": "bot",
      "text": "आपको cattle feed pellet machine की requirement है ना?"
    },
    {
      "i": 2,
      "speaker": "caller",
      "text": "हाँ।"
    },
    {
      "i": 3,
      "speaker": "bot",
      "text": "आप जिस seller को call कर रहे थे वो available नहीं है और मैं IndiaMART से बोल रही हूं।"
    },
    {
      "i": 4,
      "speaker": "bot",
      "text": "मैं देख पा रही हूं आपको production capacity 50 kilograms per hour ही चाहिए ना?"
    },
    {
      "i": 5,
      "speaker": "caller",
      "text": "हाँ।"
    },
    {
      "i": 6,
      "speaker": "caller",
      "text": "ठीक है?"
    },
    {
      "i": 7,
      "speaker": "caller",
      "text": "अब processed material के बारे में बात कर लेते हैं।"
    },
    {
      "i": 8,
      "speaker": "caller",
      "text": "आपको कौन सा चाहिए जैसे HDPE, LDPE, PP या कुछ और?"
    },
    {
      "i": 9,
      "speaker": "caller",
      "text": "नमस्ते क्या आप अभी line पर हैं?"
    },
    {
      "i": 10,
      "speaker": "caller",
      "text": "Please बताइए।"
    }
  ]
}
